def ts(ms): s=ms//1000; return f"{s//60}:{s%60:02d}"
blocos=[]; falantes=[]
for n,ad in ADS.items():
    W=f'VSL-Pipeline-Y0{n}'
    C=json.load(open(f'{W}/chunks.json')); assert len(C)==len(ad['pt']),(n,len(C),len(ad['pt']))
    falas=[{"falante":ad['falantes'][c['spk']],"ts":ts(c['start']),"en":c['en'],"pt":p} for c,p in zip(C,ad['pt'])]
    for f in falas:
        if f['falante'] not in falantes: falantes.append(f['falante'])
    prints=[]
    for s,sl,l in ad['prints']:
        arq=f"ad{n:02d}_{sl}_00-{s//60:02d}-{s%60:02d}.jpg"
        Image.open(f'{W}/full/{s:05d}.jpg').convert('RGB').save(f'VSL-Pipeline-ADS5/frames/{arq}','JPEG',quality=88)
        prints.append({"ts":ts(s*1000),"legenda":l,"arquivo":arq})
    blocos.append({"n":n,"titulo":ad['titulo'],"inicio":"0:00","fim":ts(C[-1]['end']),"falas":falas,"prints":prints})
doc={"titulo":"ADS — pasta Drive (5 anúncios, lote 4) — Transcrição EN + Tradução PT-BR + Prints",
 "fonte":"Fonte: pasta do Drive com 5 vídeos (video-08-07, 16-07, 23-09, 12-10 e 14-10-2026), ordenados pela data do nome. Transcrição: AssemblyAI (speaker labels). Tradução fiel: nomes, marcas, valores em dólares e referências mantidos como falados. Os ADs 01 e 03 usam o mesmo personagem ('Texas truck talk'). O AD 04 diz 'her' no fechamento, embora o entrevistado seja um homem — mantido como falado.",
 "nota_prints":"Minutagens: cada trecho traz o [m:ss] em que começa. Prints: frames dos momentos em que muda a cena, o lettering ou aparece a prova, com legenda descrevendo a imagem e o texto queimado no vídeo, nomeados adNN_descricao_HH-MM-SS.jpg na pasta frames/.",
 "falantes":falantes,"blocos":blocos}
json.dump(doc,open('VSL-Pipeline-ADS5/doc.json','w'),ensure_ascii=False,indent=1)
print(len(blocos),'ads',sum(len(b['falas']) for b in blocos),'trechos',sum(len(b['prints']) for b in blocos),'prints')
